use serde_json::{json,Value};use sha2::{Sha256,Digest};use std::{fs,process::Command};
const R:&str="/home/ubuntu/src/zopro-perf-work/swiss-control-audit175";
fn hash(p:&str)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn read(p:&str)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn main(){let mut rows=vec![];for(label,root,variant)in[("accepted","/home/ubuntu/src/zopro-perf-work/balanced-kh-production","candidate"),("OFF","/home/ubuntu/src/zopro-perf-work/swiss-groups-sdk175","control")]{let receipt=read(&format!("{root}/native/{variant}/artifacts.json"));for(p,h)in receipt["input_pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let binary=receipt["binary"].as_str().unwrap();let before=hash(binary);assert_ne!(before,receipt["binary_sha256"]);let command=read(&format!("{root}/native/{variant}/command.json"));let args=command["argv"].as_array().unwrap();let mut c=Command::new(args[0].as_str().unwrap());for a in&args[1..]{c.arg(a.as_str().unwrap());}for(k,v)in command["environment"].as_object().unwrap(){c.env(k,v.as_str().unwrap());}let output=c.output().unwrap();fs::write(format!("{R}/restore-{label}-stdout.log"),output.stdout).unwrap();fs::write(format!("{R}/restore-{label}-stderr.log"),output.stderr).unwrap();assert!(output.status.success());let after=hash(binary);assert_eq!(after,receipt["binary_sha256"]);rows.push(json!({"variant":label,"relink_used_original_pinned_inputs":true,"original_link_command":command,"rewritten_sha256":before,"restored_sha256":after,"exact_original_hash_restored":true,"new_capture_or_test":false}));fs::write(format!("{R}/restoration.json"),serde_json::to_vec_pretty(&json!({"tool_side_effect":"objcopy --dump-section without output filename rewrote input ELF containers","no_benchmark_run_after_rewrite":true,"restoration":"relink exact original driver with exact original frozen libraries and command; no Cargo rebuild or tests/captures","rows":rows})).unwrap()).unwrap();println!("Restored {label} exact original checksum {after}");}}
